// Cut Glass - color and sparkle. STATIC (no t/u_time). Runs INSIDE shadeSurface().
// Glass is nearly colorless: the realism is the facet shading (from the displacement)
// plus a specular glint on facets facing the light. In scope: pModel, n_model,
// viewDir_model, mainLight_model. Dock colors: u_col1 = glass tint, u_col2 = glint.

float SPARKLE_SHARP = 90.0;   // glint sharpness (exponent)  [30 .. 160]
float SPARKLE_GAIN  = 1.4;    // sparkle intensity           [0.5 .. 3.0]
float FRESNEL_LIFT  = 1.25;   // grazing-edge brightness     [1.0 .. 1.6]

// base glass tint: u_col1, slightly modulated by viewing angle (cheap Fresnel).
float fres = pow(1.0 - max(dot(n_model, viewDir_model), 0.0), 3.0);
vec3 glass = mix(ubuf.u_col1, ubuf.u_col1 * FRESNEL_LIFT, fres);

// Narrow specular glint computed HERE (independent of the useSpecular toggle).
vec3 H = normalize(mainLight_model + viewDir_model);
float sparkle = pow(max(dot(n_model, H), 0.0), SPARKLE_SHARP);

// the glint tends toward u_col2 (usually white): added on top of the tint.
glass += ubuf.u_col2 * sparkle * SPARKLE_GAIN;

textureCol = glass;

